xiao_0",302002,60,false,false,1,false,false,"1",false,false,"-50,0,1",false,"-50,0,1","-50,0,1","-50,0,1",0,false,false,false,false,false,false,false,false,false,false,false,false,"yuanxiao_0"},h)g[40010703]=b({e[9044],40010703,19,39,447,"「ふん！ やっ！ 四風連打ぁ！\nねえ、お人好し君も、この役名って拳法の名前に似てると思うでしょ？\nそこで、功夫の要領で拳法を考えてみたんだけど、どうかなあ？」",20000107,2,"deco/character/yuanxiao_gf",0,1,4625,5000,2378,4030,5333,4666,6000,4433,11017,8000,5333,"yuanxiao_gf"},h)g[40010801]=b({e[17044],40010801,false,189,448,false,20000108,false,"deco/character/jiantongying",302002,60,false,false,1,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"jiantongying"},h)g[40010802]=b({e[17044],40010802,1,4,449,false,20000108,1,"deco/character/jiantongying_0",302002,60,false,false,1,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"jiantongying_0"},h)g[40010803]=b({e[17044],40010803,999,190,450,false,20000108,3,"deco/character/jiantongying_hf",false,false,false,false,1,false,false,"1",0,1,5000,5000,2668,6044,8000,9333,10266,8000,18000,8000,8000,"jiantongying_1"},h)g[40010901]=b({e[17044],40010901,false,191,451,false,20000109,false,"deco/character/yuanbanlin",302002,60,false,false,1,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"yuanbanlin"},h)g[40010902]=b({e[17044],40010902,1,4,452,false,20000109,1,"deco/character/yuanbanlin_0",302002,60,false,false,1,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"yuanbanlin_0"},h)g[40010903]=b({e[17044],40010903,999,190,453,false,20000109,3,"deco/character/yuanbanlin_hf",false,false,false,false,1,false,false,"1",0,1,5286,5000,2779,5093,5333,5000,11766,4000,10000,8000,5333,"yuanbanlin_1"},h)g[40011001]=b({e[17044],40011001,false,192,454,false,20000110,false,"deco/character/saber",302002,60,false,false,1,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"aertuoliya"},h)g[400110